import requests
import os
from identity_client import FIREBASE_WEB_API_KEY
from identity_models import RegisterUserRequest, RegisterUserResponse

FIREBASE_SIGNUP_URL = "https://identitytoolkit.googleapis.com/v1/accounts:signUp?key="

def register_user(request: RegisterUserRequest) -> RegisterUserResponse:
    if not FIREBASE_WEB_API_KEY:
        raise ValueError("Firebase Web API Key not found. Please set FIREBASE_API_KEY environment variable.")

    url = f"{FIREBASE_SIGNUP_URL}{FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/json"}
    payload = {
        "email": request.email,
        "password": request.password,
        "returnSecureToken": True
    }

    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status() # Raise an exception for HTTP errors

    data = response.json()
    return RegisterUserResponse(
        id_token=data["idToken"],
        refresh_token=data["refreshToken"],
        local_id=data["localId"]
    )

# [SAME-SCENARIO] refresh_session.py - refreshes an expired session or access token
# Provider: Google Firebase Authentication

import requests
from identity_client import FIREBASE_WEB_API_KEY
from identity_models import RefreshSessionRequest, RefreshSessionResponse

FIREBASE_REFRESH_TOKEN_URL = "https://securetoken.googleapis.com/v1/token?key="

def refresh_session(request: RefreshSessionRequest) -> RefreshSessionResponse:
    if not FIREBASE_WEB_API_KEY:
        raise ValueError("Firebase Web API Key not found. Please set FIREBASE_API_KEY environment variable.")

    url = f"{FIREBASE_REFRESH_TOKEN_URL}{FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/x-www-form-urlencoded"}
    payload = {
        "grant_type": "refresh_token",
        "refresh_token": request.refresh_token
    }

    response = requests.post(url, headers=headers, data=payload)
    response.raise_for_status() # Raise an exception for HTTP errors

    data = response.json()
    return RefreshSessionResponse(
        id_token=data["id_token"],
        refresh_token=data["refresh_token"],
        local_id=data["user_id"]
    )

# [SAME-SCENARIO] password_reset.py - starts a password reset flow for a local account
# Provider: Google Firebase Authentication

import requests
from identity_client import FIREBASE_WEB_API_KEY
from identity_models import PasswordResetRequest, PasswordResetResponse

FIREBASE_PASSWORD_RESET_URL = "https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key="

def password_reset(request: PasswordResetRequest) -> PasswordResetResponse:
    if not FIREBASE_WEB_API_KEY:
        raise ValueError("Firebase Web API Key not found. Please set FIREBASE_API_KEY environment variable.")

    url = f"{FIREBASE_PASSWORD_RESET_URL}{FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/json"}
    payload = {
        "requestType": "PASSWORD_RESET",
        "email": request.email
    }

    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status() # Raise an exception for HTTP errors

    data = response.json()
    return PasswordResetResponse(
        email=data["email"]
    )

# [LATER-STEP] profile_note_store.py - Persist onboarding notes and support metadata in a managed document store
# Provider: Google Cloud Firestore

import os
import google.cloud.firestore

def store_profile_note(user_id: str, note_data: dict):
    # Initialize Firestore client
    db = google.cloud.firestore.Client()

    # Reference to a collection and document
    doc_ref = db.collection('onboarding_notes').document(user_id)

    # Set the data for the document
    doc_ref.set(note_data)

def get_profile_note(user_id: str) -> dict:
    db = google.cloud.firestore.Client()
    doc_ref = db.collection('onboarding_notes').document(user_id)
    doc = doc_ref.get()
    if doc.exists:
        return doc.to_dict()
    else:
        return {}
